faq=ph('Frequently asked questions','Straight answers before you request an audit.','Honest scope and practical expectations.')+'<section><div class="wrap faq">'+''.join(f'<details><summary><h2>{q}</h2></summary><p>{a}</p></details>' for q,a in FAQ)+'</div></section>'+cta();write('faq/index.html','Contractor Growth System FAQ | Top Shelf Agency','Answers about the Growth Audit, scope, timing, tools, and guarantees.',faq,{'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in FAQ]})
contact=ph('Contact Top Shelf Agency','Talk directly with a North Jersey founder.','For a business review, the Growth Audit form gives Steve the context needed.')+f'<section><div class="wrap split"><div><h2>Request an audit</h2><p>The best first step for plumbing and electrical owners.</p><a class="btn" href="/growth-audit/">Get My Free Growth Audit</a></div><div><h2>Email</h2><p><a href="mailto:{EMAIL}">{EMAIL}</a></p><p>A public phone number will be added only after verification.</p></div></div></section>';write('contact/index.html','Contact Top Shelf Agency | North Jersey','Contact Top Shelf Agency or request a free Growth Audit.',contact)
privacy=ph('Privacy Policy','How Top Shelf handles website and audit-request information.','Effective July 16, 2026. Review before production when final systems are confirmed.')+f'<section><div class="wrap prose"><h2>Information collected</h2><p>We may collect submitted contact and business details plus referral parameters.</p><h2>How it is used</h2><p>To respond, prepare an audit, evaluate fit, maintain records, and meet security or legal obligations.</p><h2>Providers and messages</h2><p>Approved hosting, CRM, email, text, scheduling, security, and measurement providers may process data. With consent, we may contact you about the audit. Rates may apply; consent is not a purchase condition; reply STOP to opt out.</p><h2>Your choices</h2><p>Request access, correction, deletion, or preference changes at <a href="mailto:{EMAIL}">{EMAIL}</a>. Do not submit passwords or customer data.</p></div></section>';write('privacy/index.html','Privacy Policy | Top Shelf Agency','Privacy information for the Top Shelf website and Growth Audit request.',privacy)
terms=ph('Website Terms','Terms for using the Top Shelf website.','Effective July 16, 2026. Final service terms require a separate agreement.')+f'<section><div class="wrap prose"><h2>Informational website</h2><p>This site does not create a client relationship, proposal, or guarantee of services, timing, revenue, leads, savings, or results.</p><h2>Audit and services</h2><p>Public observations are not verified gaps until confirmed. Paid work, scope, price, approval, data handling, and cancellation require a written agreement.</p><h2>Contact</h2><p>Questions: <a href="mailto:{EMAIL}">{EMAIL}</a>.</p></div></section>';write('terms/index.html','Website Terms | Top Shelf Agency','Terms for using the Top Shelf website and requesting a Growth Audit.',terms)
thanks=ph('Growth Audit request received','Thank you for sharing the context Steve needs.','This page follows only a successful configured form response.')+f'<section><div class="wrap prose"><h2>What happens next</h2><p>Steve will review the information. Corrections: <a href="mailto:{EMAIL}">{EMAIL}</a>.</p></div></section>';write('thank-you/index.html','Growth Audit Request Received | Top Shelf Agency','Confirmation for a Growth Audit request.',thanks,noindex=True)
write('404.html','Page Not Found | Top Shelf Agency','The requested page could not be found.',ph('404','This page is not on the shelf.','The address may have changed.')+'<section><div class="wrap"><a class="btn" href="/">Back to Home</a></div></section>',noindex=True)
