 p=R/old/'index.html';p.parent.mkdir(parents=True,exist_ok=True);p.write_text('<!doctype html><meta charset="utf-8"><meta name="robots" content="noindex"><link rel="canonical" href="https://topshelfagency.biz/growth-package/"><meta http-equiv="refresh" content="0;url=/growth-package/"><a href="/growth-package/">Contractor Growth Package</a>',encoding='utf-8')
